const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// These are new examples for the workshop, not transcriptions or quotations from the videos.
export const WRITING_IDEAS={
 wartke:[
  {id:'barbara',title:'Wörter verlängern',observation:'In «Barbaras Rhabarberbar» werden Wörter zusammengesetzt und wieder aufgegriffen. So wächst mit dem Klang auch die Geschichte.',idea:'Erfinde einen Ort und eine Person mit demselben Anlaut. Ein neues zusammengesetztes Wort soll die nächste Zeile auslösen.',example:'Mira macht im Mondschein Marmelade.\nDie Mondscheinmarmelade riecht nach Meer.\nAm Morgen steht ein Matrose vor dem Laden.\nEr bringt die leeren Gläser wieder her.',words:['Mira','Mondschein','Marmelade','Matrose','Meer','Markt','Marmeladenglas','Mitternacht'],try:'Was würde der Matrose gegen ein neues Glas eintauschen?'},
  {id:'dach',title:'Mit «sch» schreiben',observation:'Beim Dachdecker-Stück hört man, wie ähnliche Laute den Vortrag bestimmen. Für einen eigenen Versuch genügt erst einmal eine einzige Lautgruppe.',idea:'Sammle Wörter mit «sch». Verbinde zwei davon durch eine Handlung, statt sie nur aufzuzählen.',example:'Schorsch schiebt Schachteln durch den Schnee.\nIm Schaufenster schwimmt eine Tasse Tee.\nEr schüttelt den Kopf und schaut noch mal hin:\nDa sitzt ein Schiff in der Tasse drin.',words:['Schachtel','Schnee','Schaufenster','schieben','Schiff','schaukeln','schmal','schimmern'],try:'Welche Zeile wird leichter sprechbar, wenn ein Wort wegfällt?'},
  {id:'er',title:'Vier Zellbestandteile',observation:'Der Retikulum-Rap macht einen langen Fachbegriff hörbar. Für eigene Lernverse lassen sich erst einmal die Aufgaben der Zellbestandteile auf kurze Zeilen verteilen.',idea:'Gib jeder Zeile einen Zellbestandteil. Ein Reim kann später dazukommen; die Aufgaben müssen dabei stimmen.',example:'Raues ER: Ribosomen an der Oberfläche.\nHier entstehen bestimmte Proteine.\nGlattes ER: unter anderem Lipide.\nGolgi verändert, sortiert und verpackt.',words:['Ribosomen','raues ER','glattes ER','Proteine','Lipide','Golgi','sortieren','verpacken'],try:'Welche Zeile könntest du nach dem Vorlesen ohne Vorlage erklären?'},
  {id:'mito',title:'Von aussen nach innen',observation:'Im Mitochondrien-Beitrag treffen Fachwörter auf Rhythmus und Wiederholung. Eine räumliche Reihenfolge kann beim Erinnern helfen.',idea:'Geh in vier Zeilen von aussen nach innen. Verbinde jeden Ort mit einem Begriff.',example:'Zwei Membranen aussenrum.\nDie innere faltet sich zu Cristae.\nDie Matrix liegt in ihrem Innern.\nAn der inneren Membran entsteht ATP.',words:['äussere Membran','innere Membran','Cristae','Matrix','ATP','Falten','innen','aussen'],try:'Zeichne die vier Zeilen als kleine Skizze. Fehlt im Text ein Ort?'},
  {id:'grundgesetz',title:'Zwei Stimmen',observation:'Wartke und die Band beziehen sich auf die ersten fünf Artikel des deutschen Grundgesetzes. Der Rap verbindet Grundsätze mit einer eigenen Haltung.',idea:'Schreib zwei Stimmen, die verschiedener Meinung sind. Ihre Verschiedenheit soll stehen bleiben.',example:'Deine Stimme ist nicht meine.\nDu setzt den Punkt an einen andern Ort.\nIch schreibe meine Antwort daneben.\nIch streiche deine nicht fort.',words:['Stimme','Würde','Freiheit','Grenze','widersprechen','zuhören','daneben','Antwort'],try:'Was verändert sich, wenn beide Stimmen abwechselnd je eine Zeile sprechen?'},
  {id:'schriften',title:'Fragen an einen Satz',observation:'«Die heiligen Schriften 2.0» handelt vom Umgang mit religiösen Texten und ihrem Missbrauch. Für einen eigenen Text lässt sich die Frage nach dem Lesen und Auslegen aufnehmen.',idea:'Eine Person beruft sich auf einen Satz. Die andere fragt nach seinem Zusammenhang.',example:'Du sagst: So steht es geschrieben.\nIch frage: Wer liest es so?\nDu zeigst auf dieselbe Seite.\nIch suche den Satz davor.',words:['Seite','Rand','Auslegung','Stimme','fragen','lesen','davor','Zusammenhang'],try:'Lass die zweite Stimme einmal mit einer Beobachtung antworten statt mit einer Frage.'},
  {id:'wald',title:'Zwei Fundstücke',observation:'«Hambacher Wald» ist ein Protestlied zu einem konkreten Ort. Ein eigener Text kann ebenfalls mit etwas Sichtbarem anfangen, bevor er eine Forderung formuliert.',idea:'Schreib über einen Ort, der sich verändert. Zwei Fundstücke können genügen, um den Konflikt zu zeigen.',example:'Am Rand des Wegs liegt eine Kastanie.\nDaneben die Spur einer Maschine.\nIch stecke die Kastanie ein.\nDie Spur bleibt.',words:['Kastanie','Weg','Maschine','Spur','Rinde','Wurzel','einstecken','bleiben'],try:'Welche zusätzliche Zeile würde zu viel erklären? Lass sie probeweise weg.'}
 ],
 clara:[
  {id:'DepJatpumXF',title:'Farben im selben Raum',observation:'Der Beitrag verbindet ein Farbbild mit der Frage, wie sehr man sich für jemanden verändert. Daraus kann eine eigene Szene mit sichtbaren Farbspuren entstehen.',idea:'Zwei Menschen hinterlassen Spuren im selben Raum. Beschreibe die Beziehung über Farben und Dinge.',example:'Dein Blau bleibt an meinem Ärmel.\nMein Gelb steht noch am Fensterbrett.\nWir waschen zusammen die Pinsel.\nFür einen Moment ist das Wasser grün.',words:['Blau','Gelb','Ärmel','Fensterbrett','Pinsel','Wasser','abfärben','auswaschen'],try:'Tausche den letzten Gegenstand aus. Ändert sich dadurch auch die Beziehung?'},
  {id:'DaUTcv1NQOr',title:'Zwei Menschen in der Küche',observation:'Im Beitrag geht es um Freundschaft im gemeinsamen Alltag. Nähe lässt sich auch zeigen, ohne sie ausdrücklich zu benennen.',idea:'Zwei Menschen sind im selben Zimmer. Schreib nur auf, was sie tun.',example:'Du schiebst mir den Teller herüber.\nIch lasse dir den letzten Rand vom Brot.\nDraussen fährt der Bus vorbei.\nKeiner von uns sieht auf die Uhr.',words:['Teller','Brot','Küche','Bus','Uhr','herüberschieben','warten','Schweigen'],try:'Streiche jedes Wort, das ein Gefühl direkt benennt. Ist die Nähe trotzdem zu erkennen?'},
  {id:'DUKcqZ4CBMp',title:'Ein anderer Schulweg',observation:'Lösel nimmt für diesen Text einen Satz von Carl Sandburg zum Ausgangspunkt. Die eigene Schreibidee bleibt bei einem vertrauten Ort und kleinen Veränderungen.',idea:'Stell dir deinen Schulweg nach dem Ende eines Konflikts vor. Was würdest du zuerst bemerken?',example:'Vor dem Haus liegt wieder Kreide.\nJemand hat ein Tor auf die Strasse gemalt.\nDer Bäcker lässt die Türe offen.\nIch gehe den längeren Weg.',words:['Kreide','Strasse','Türe','Bäckerei','Schulweg','wieder','offen','Umweg'],try:'Was könnte an einem einzigen Geräusch hörbar werden? Ergänze eine Zeile dazu.'},
  {id:'Ddx3xGsNbxB',title:'Die kalte Tasse',observation:'Der Beitrag handelt davon, für andere da zu sein und die eigenen Grenzen zu bemerken. Ein Gegenstand kann diesen Moment sichtbar machen.',idea:'Erzähl von einer Person, die sich um jemanden kümmert. Ein kleines Detail soll zeigen, was ihr selbst fehlt.',example:'Ich stelle dir die Tasse hin.\nDen Zucker kennst du längst auswendig.\nAls ich mich endlich zu dir setze,\nist mein Kaffee kalt.',words:['Tasse','Zucker','Kaffee','Stuhl','einschenken','hinsetzen','warten','kalt'],try:'Was würde sich ändern, wenn der andere die letzte Handlung übernimmt?'},
  {id:'De7MToNOy6d',title:'Zwei Blicke auf denselben Tag',observation:'Der Beitrag unterbricht einen abwertenden Gedanken. Für eine eigene Szene können zwei Stimmen dieselbe Beobachtung unterschiedlich lesen.',idea:'Eine Figur urteilt streng über sich. Jemand anderes antwortet mit etwas, das er wirklich beobachtet hat.',example:'Du sagst: Ich habe nichts geschafft.\nIch sage: Du hast angerufen.\nDu siehst den Stapel auf dem Tisch.\nIch sehe deine Nummer im Verlauf.',words:['Anruf','Stapel','Tisch','Nummer','Verlauf','sagen','sehen','antworten'],try:'Ersetze den Anruf durch eine andere kleine Handlung. Bleibt die Antwort glaubwürdig?'},
  {id:'C2UM_qzNwGl',title:'Ein freier Platz',observation:'Der Beitrag bezieht öffentlich Position. Ein eigener Text kann einen Widerspruch an einer Alltagshandlung zeigen.',idea:'Jemand sagt das eine und tut das andere. Lass die Szene ohne erklärenden Kommentar enden.',example:'Er sagt, hier könne jeder sitzen.\nDann stellt er seine Tasche auf den Stuhl.\nDie Frau mit dem Koffer bleibt stehen.\nDer Zug fährt los.',words:['Tasche','Stuhl','Koffer','Zug','sitzen','stehen','Platz','losfahren'],try:'Versuch die Szene aus der Sicht der Tasche zu erzählen. Welche Fassung ist schärfer?'},
  {id:'DPSxE6-CFmU',title:'Ein Schritt zurück',observation:'Der Beitrag spricht über Schönheitsideale. Für den eigenen Text kann ein vertrauter Gegenstand im Mittelpunkt stehen; persönliche Erfahrungen sind dafür nicht nötig.',idea:'Schreib eine Szene vor einem Spiegel. Lass eine Handlung zeigen, wie die Figur mit den Erwartungen umgeht.',example:'Im Spiegel fehlt immer ein Stück.\nEinmal das Kinn, einmal die Stirn.\nIch nehme einen Schritt Abstand.\nJetzt passt das Fenster mit hinein.',words:['Spiegel','Fenster','Abstand','Licht','Rahmen','Schritt','ansehen','zurücktreten'],try:'Welche Wirkung hat es, wenn die Figur den Spiegel am Ende ganz verlässt?'},
  {id:'DS6xxyiCP7v',title:'Der zweite Schlüssel',observation:'Der Jahresrückblick stellt sichtbare Erfolge und weniger sichtbare Veränderungen nebeneinander. Ein einzelner Gegenstand kann von so einer Veränderung erzählen.',idea:'Zeig an einem Ding, was heute anders ist als früher.',example:'Im Januar blieb der zweite Schlüssel\nin der Schublade neben den Quittungen.\nHeute hängt er an deinem Bund.\nDie Schublade klemmt noch immer.',words:['Schlüssel','Schublade','Quittung','Januar','heute','aufheben','mitnehmen','klemmen'],try:'Erzähl dieselbe Veränderung mit einem anderen Gegenstand.'}
 ]
};
export function writingIdea(unit,id){return WRITING_IDEAS[unit]?.find(item=>item.id===id)||WRITING_IDEAS[unit]?.[0];}
export function appendWorkshopText(current,addition){
 if(typeof current!=='string'||typeof addition!=='string')throw Error('Text erwartet.');
 if(!addition||current.includes(addition))return current;
 const value=current+(current?(current.endsWith('\n\n')?'':current.endsWith('\n')?'\n':'\n\n'):'')+addition;
 if(value.length>30000)throw Error('Der Text ist zu lang. Kürze ihn vor dem Einfügen.');
 return value;
}
export function collectWorkshopWords(current,words){
 const present=new Set(current.split(/\r?\n/).map(s=>s.trim()));
 const fresh=[];for(const word of words)if(!present.has(word)){present.add(word);fresh.push(word);}
 return appendWorkshopText(current,fresh.join('\n'));
}
export function mountWritingInspiration(root,{unit,selected,items,exampleRoot,onSelect,onInsert,onCollect,onRules}){
 let active=writingIdea(unit,selected);
 const sources=new Map(items.map(item=>[item.id,item]));
 function draw(){
  const source=sources.get(active.id);
  root.innerHTML=`<div class="writing-source-select"><label class="field" for="writing-source">Ideen zu einem Video</label><select id="writing-source">${WRITING_IDEAS[unit].filter(idea=>sources.has(idea.id)).map(idea=>`<option value="${idea.id}" ${idea.id===active.id?'selected':''}>${esc(sources.get(idea.id).title)}</option>`).join('')}</select></div><section class="writing-source-card"><div class="idea-video" id="idea-video"><button id="idea-play" aria-label="${esc(source.title)} · Video laden">${source.kind==='youtube'?`<img src="https://i.ytimg.com/vi/${esc(source.video)}/hqdefault.jpg" alt="Vorschaubild des Originalvideos" referrerpolicy="no-referrer">`:source.kind==='instagram'?'<img class="idea-clara-photo" src="assets/clara-loesel-offiziell.jpg" alt="Clara Lösel mit einem Notizbuch">':`<span class="idea-video-title">${esc(source.title)}</span>`}<span class="idea-play-label">▶ ${source.kind==='instagram'?'Reel':'Video'} ansehen</span></button></div><a class="idea-source-link" href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)} · Original</a>${source.sensitive?`<p class="small idea-sensitive">${esc(source.sensitive)}</p>`:''}<p class="idea-observation">${esc(active.observation)}</p><p class="idea-suggestion">${esc(active.idea)}</p><p class="idea-variation">${esc(active.try)}</p><h3>Wörter zum Weiterarbeiten</h3><div class="idea-wordbank">${active.words.map((word,i)=>`<button data-idea-word="${i}" aria-label="${esc(word)} zu den Notizen hinzufügen">${esc(word)}</button>`).join('')}</div><div class="idea-tool-links"><button id="idea-collect">Alle Wörter sammeln</button><button id="idea-rules">Passende Grammatik öffnen</button></div><p id="idea-status" class="small" role="status" aria-live="polite"></p></section>`;
  const exampleHost=exampleRoot||root;
  const exampleHTML=`<section class="idea-example"><p class="idea-example-label">Beispiel dieser Werkstatt · kein Originaltext</p><h2>${esc(active.title)}</h2><p class="idea-verse">${esc(active.example)}</p><button id="idea-insert">Beispiel in meinen Entwurf einfügen</button></section>`;
  if(exampleRoot)exampleRoot.innerHTML=exampleHTML;else root.insertAdjacentHTML('beforeend',exampleHTML);
  const tell=text=>root.querySelector('#idea-status').textContent=text;
  root.querySelector('#writing-source').onchange=event=>{active=writingIdea(unit,event.target.value);onSelect(active.id);draw();};
  root.querySelector('#idea-play').onclick=()=>{const src=source.kind==='youtube'?`https://www.youtube-nocookie.com/embed/${source.video}`:source.kind==='vimeo'?`https://player.vimeo.com/video/${source.video}?dnt=1`:`https://www.instagram.com/p/${source.id}/embed/`;root.querySelector('#idea-video').innerHTML=`<iframe title="${esc(source.title)}" src="${esc(src)}" allow="encrypted-media; fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;};
  exampleHost.querySelector('#idea-insert').onclick=()=>{try{onInsert(active.example);tell('Das Beispiel steht im Entwurf. Dein bisheriger Text bleibt erhalten.');}catch(error){tell(error.message);}};
  root.querySelectorAll('[data-idea-word]').forEach(button=>button.onclick=()=>{try{onCollect([active.words[Number(button.dataset.ideaWord)]]);button.classList.add('collected');tell('In den Notizen gesammelt.');}catch(error){tell(error.message);}});
  root.querySelector('#idea-collect').onclick=()=>{try{onCollect(active.words);root.querySelectorAll('[data-idea-word]').forEach(button=>button.classList.add('collected'));tell('Die Wörter stehen in deinen Notizen.');}catch(error){tell(error.message);}};
  root.querySelector('#idea-rules').onclick=()=>onRules(active.id);
 }
 draw();
}
